"use client";
/* Dice, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Dice(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("dice"); }, []);
  return React.createElement("piix-pal", { "pal": "dice", ...piixAttrs(props) });
}

export default Dice;
